Demonstrates acquiring a distributed lock using atomic token generation and lease validation.

```python
class DistributedLockManager:
    def __init__(self):
        self.locks = {}
        self.fencing_counter = 0

    def acquire_lock(self, resource_id, client_id, lease_duration):
        current_time = time.time()
        lock_state = self.locks.get(resource_id)

        if lock_state and lock_state['expires_at'] > current_time:
            return None, 0 # Locked

        self.fencing_counter += 1
        new_state = {
            'client_id': client_id,
            'expires_at': current_time + lease_duration,
            'token': self.fencing_counter
