        lock_state = self.locks.get(resource_id)

        if lock_state and lock_state['expires_at'] > current_time:
            return None, 0 # Locked

        self.fencing_counter += 1
        new_state = {
            'client_id': client_id,
            'expires_at': current_time + lease_duration,
            'token': self.fencing_counter
        }
        self.locks[resource_id] = new_state
        return new_state['token'], True
