Demonstrates a lock-free root-list insertion step using atomic CAS and hazard pointer protection for a binomial heap node.

```cpp
bool insert_root(std::atomic<Node*>& root_list_head, Node* new_node, HazardPointerRegistry& hp_reg) {
    while (true) {
        Node* old_head = root_list_head.load(std::memory_order_acquire);
        hp_reg.protect(0, old_head);
        if (root_list_head.load(std::memory_order_acquire) != old_head) continue;
        new_node->sibling = old_head;
        if (root_list_head.compare_exchange_weak(old_head, new_node, std::memory_order_release, std::memory_order_relaxed)) {
            hp_reg.clear(0);
            return true;
        }
    }
}
```

