Demonstrates the atomic node structure and a lock-free merge attempt utilizing hazard pointers.

```cpp
#include <atomic>
#include <memory>

struct Node {
    int priority;
    int npl;
    std::atomic<Node*> left;
    std::atomic<Node*> right;
};

Node* merge_nodes(Node* h1, Node* h2) {
    if (!h1) return h2;
    if (!h2) return h1;
    if (h1->priority < h2->priority) std::swap(h1, h2);
    Node* merged = merge_nodes(h1->right.load(), h2);
    h1->right.store(merged);
    if ((h1->left.load() ? h1->left.load()->npl : 0) < (h1->right.load() ? h1->right.load()->npl : 0)) {
        Node* temp = h1->left.load();
        h1->left.store(h1->right.load());
        h1->right.store(temp);
    }
    h1->npl = (h1->right.load() ? h1->right.load()->npl : 0) + 1;
    return h1;
}
```

