class ConcurrentCountMinSketch {
    int depth;
    int width;
    std::vector<std::vector<std::atomic<uint64_t>>> table;
public:
    ConcurrentCountMinSketch(int d, int w) : depth(d), width(w) {
        table.resize(depth, std::vector<std::atomic<uint64_t>>(width));
        for(int i=0; i<depth; ++i) {
            for(int j=0; j<width; ++j) {
                table[i][j].store(0, std::memory_order_relaxed);
