        self.value = value
        self.next = None

class EpochManager:
    def __init__(self):
        self.epoch = 0
        self.threads = threading.local()

    def enter(self):
        self.threads.epoch = self.epoch

    def leave(self):
        self.threads.epoch = None

class MemTable:
    def __init__(self):
        self.head = ConcurrentLSMNode(None, None)

