#include <atomic>
#include <vector>

class ConcurrentVectorClock {
    std::vector<std::atomic<uint64_t>> timestamps;
public:
    void increment(size_t node_id) {
        uint64_t current = timestamps[node_id].load(std::memory_order_relaxed);
        while (!timestamps[node_id].compare_exchange_weak(current, current + 1,
            std::memory_order_release, std::memory_order_relaxed));
    }
};
```

